addEventListener('scroll',()=>{velocity+=((scrollY-lastY)-velocity)*.22;lastY=scrollY;root.style.setProperty('--velocity',Math.min(Math.abs(velocity),80));root.style.setProperty('--page-y',scrollY.toFixed(1));const speed=Math.round(118+Math.min(Math.abs(velocity)*2.7,102));$$('[data-speed]').forEach(n=>n.textContent=speed);const sections=$$('[data-section]');let near=sections[0];sections.forEach(s=>{const box=s.getBoundingClientRect(),progress=Math.max(0,Math.min(1,(innerHeight-box.top)/(innerHeight+box.height)));s.style.setProperty('--scene',progress.toFixed(4));if(Math.abs(box.top)<Math.abs(near.getBoundingClientRect().top))near=s});$('.counter').textContent=`${near?.dataset.section||'01'} / 10`},{passive:true});
function output(c){return musicMaster||c.destination}function tone(freq,duration=.12,volume=.025,type='sawtooth'){const c=audio,o=c.createOscillator(),g=c.createGain(),t=c.currentTime;o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(volume,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g).connect(output(c));o.start(t);o.stop(t+duration+.02)}
function drum(){const c=audio,t=c.currentTime,b=c.createBuffer(1,Math.floor(c.sampleRate*.04),c.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=Math.random()*2-1;const s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=b;f.type='highpass';f.frequency.value=5500;g.gain.setValueAtTime(.025,t);g.gain.exponentialRampToValueAtTime(.0001,t+.04);s.connect(f).connect(g).connect(output(c));s.start()}
function startMusic(){const C=AudioContext||webkitAudioContext;audio??=new C;audio.resume();musicMaster=audio.createGain();musicMaster.gain.value=.34;musicMaster.connect(audio.destination);beat=0;const bass=[55,55,65.4,73.4,55,82.4,73.4,65.4],arp=[220,277.2,329.6,440,329.6,277.2,246.9,329.6];const tick=()=>{if(!sound)return;if(beat%2===0)tone(bass[(beat/2)%bass.length],.2,.035,'square');tone(arp[beat%arp.length],.08,.018,'sawtooth');drum();if(beat%4===0){tone(82,.1,.06,'sine')}beat++};tick();musicTimer=setInterval(tick,100)}
function stopMusic(){clearInterval(musicTimer);musicTimer=undefined;if(musicMaster){musicMaster.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+.15);setTimeout(()=>musicMaster?.disconnect(),180);musicMaster=undefined}}
function blip(){if(!sound||!audio)return;tone(95,.16,.04,'triangle')}
$('.sound').onclick=()=>{sound=!sound;$('.sound').textContent=sound?'90S DRIVE / ON':'SOUND OFF';sound?startMusic():stopMusic()};
